# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A simple yet effective (1+1)-Evolution Strategy with adaptive step-size (1/5th success rule).
# Search state: Maintains a single current best candidate point and a global isotropic step-size (sigma).
# Candidate generation: New candidates are generated by adding Gaussian noise scaled by sigma to the current best.
# Selection and replacement: Simple elitist selection; if the new candidate is better, it replaces the current best.
# Adaptation: Multiplies sigma by 1.1 if a success occurs, and 0.82 if a failure occurs (maintaining ~20% success rate).
# Exploration mechanisms: Global Gaussian mutation across the entire search space.
# Exploitation mechanisms: Local convergence via the contraction of sigma as the search progresses.
# Boundary handling: Clamping to the provided bounds with a slight reflection/re-sampling logic if necessary.
# Budget strategy: Iteratively evaluates points until the budget is fully exhausted.
# Closest known influences: Rechenberg’s (1+1)-ES with the 1/5th success rule.
# Novelty or unusual aspects: Highly compact implementation tailored for black-box constraints.
# Failure modes: Can get trapped in local optima in highly multi-modal landscapes or struggle with narrow narrow diagonal ridges.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'lower'):
            lb, ub = func.lower, func.upper
        else:
            lb, ub = func.bounds.lb, func.bounds.ub
        
        lb = np.array(lb)
        ub = np.array(ub)
        
        # Initialize state
        curr_x = np.random.uniform(lb, ub)
        curr_y = func(curr_x)
        
        best_x = np.copy(curr_x)
        best_y = curr_y
        
        # Initial sigma as 1/5th of the range
        sigma = 0.2 * (ub - lb)
        
        evals = 1
        success_count = 0
        
        while evals < self.budget:
            # Generate candidate
            delta = np.random.normal(0, sigma)
            candidate = np.clip(curr_x + delta, lb, ub)
            
            # Evaluate
            cand_y = func(candidate)
            evals += 1
            
            # Selection
            if cand_y <= curr_y:
                curr_x = candidate
                curr_y = cand_y
                success_count += 1
                
                # Update absolute best
                if curr_y < best_y:
                    best_x = np.copy(curr_x)
                    best_y = curr_y
            else:
                success_count = 0
                
            # Adaptation (1/5th success rule)
            # Increase exploration if success, decrease if trapped
            if evals % 5 == 0:
                if success_count > 1:
                    sigma *= 1.1
                else:
                    sigma *= 0.82
                success_count = 0
                
        return best_x, best_y
